file.content:
  padding:44px 52px 40px;border-bottom:1.5px solid var(--border);
  position:relative;overflow:hidden;
}
.case-num{
  font-size:56px;font-weight:900;line-height:1;opacity:0.04;
  position:absolute;top:8px;right:36px;letter-spacing:-4px;pointer-events:none;
}
.case-tag{
  display:inline-block;font-size:16px;letter-spacing:1.5px;text-transform:uppercase;
  padding:5px 16px;border-radius:100px;margin-bottom:16px;font-weight:700;
  background:rgba(212,105,42,0.08);color:var(--accent);
}
.case-title{font-size:clamp(22px,3vw,32px);font-weight:800;letter-spacing:-0.3px;margin-bottom:6px}
.case-subtitle{font-size:16px;color:var(--text-dim);font-weight:500}
.case-body{padding:48px 52px}

/* STORY BLOCK */
.story-block{
  border-radius:16px;padding:32px 36px;margin-bottom:28px;
  position:relative;background:var(--surface2);border:1px solid var(--border);
}
.story-block .scene{
  font-size:15px;color:var(--text-muted);font-weight:600;
  letter-spacing:1px;text-transform:uppercase;margin-bottom:12px;
  padding-left:102px;position:relative;min-height:88px;display:flex;align-items:center;
}
.story-block .scene::before{
  content:'';position:absolute;left:0;top:50%;transform:translateY(-50%);
  width:88px;height:88px;
  background:url(assets/analysis-badge.jpg) no-repeat center;
  background-size:contain;
}
.story-block .narrative{
  font-size:19px;color:var(--text);line-height:1.9;font-weight:500;margin-bottom:14px;
}
.story-block .narrative:last-child{margin-bottom:0}
.story-block em{
  font-style:italic;color:var(--accent2);
  background:rgba(212,105,42,0.06);padding:1px 5px;border-radius:4px;
}

/* CHAT BUBBLE — 88px avatar */
.chat-bubble{display:flex;gap:14px;align-items:flex-start;margin:14px 0}
.chat-avatar{
  flex-shrink:0;width:88px;height:88px;border-radius:50%;overflow:hidden;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 3px 10px rgba(0,0,0,0.15);
}
.chat-avatar img{width:100%;height:100%;object-fit:cover}
.chat-avatar.coach{border:3px solid rgba(212,105,42,0.40)}
.chat-avatar.ai{border:3px solid rgba(74,139,112,0.40)}
.chat-content{flex:1;min-width:0}
.chat-name{
  font-size:16px;font-weight:700;letter-spacing:1px;text-transform:uppercase;
  margin-bottom:5px;color:var(--text-muted);
}
.chat-text{
  background:var(--surface2);border:1.5px solid var(--border);
  border-radius:0 18px 18px 18px;padding:14px 20px;
  font-size:19px;font-weight:600;color:var(--text);line-height:1.8;
}
.chat-bubble.chat-coach .chat-text{border-left:3px solid var(--accent)}
.chat-bubble.chat-ai .chat-text{border-left:3px solid var(--accent3)}
.chat-bubble.chat-coach .chat-name{color:var(--accent)}
.chat-bubble.chat-ai .chat-name{color:var(--accent3)}

/* Case color themes */
.case-card.case-g .case-tag{background:rgba(212,105,42,0.10);color:var(--accent)}
.case-card.case-g .case-num{color:var(--accent)}
.case-card.case-a .case-tag{background:rgba(74,139,112,0.10);color:var(--accent3)}
.case-card.case-a .case-num{color:var(--accent3)}
.case-card.case-d .case-tag{background:rgba(168,72,32,0.10);color:var(--accent2)}
.case-card.case-d .case-num{color:var(--accent2)}
.case-card.case-006 .case-tag{background:rgba(123,90,143,0.10);color:var(--accent4)}
.case-card.case-006 .case-num{color:var(--accent4)}
.case-card.case-007 .case-tag{background:rgba(143,90,90,0.10);color:var(--accent5)}
.case-card.case-007 .case-num{color:var(--accent5)}

/* VERDICT */
.verdict{
  background:var(--surface2);border-radius:18px;padding:30px 36px;
  margin-top:40px;position:relative;border:1.5px solid var(--border);
}
.verdict-title{font-size:19px;font-weight:700;margin-bottom:10px;display:inline-block;line-height:88px}
.verdict-header{display:flex;align-items:flex-start;gap:14px;margin-bottom:20px}
.wu-badge-img{width:88px;height:88px;flex-shrink:0}
.verdict-body{font-size:17px;color:var(--text-dim);line-height:1.9;font-weight:500}
.rules-strip{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}
.rule-chip{
  font-size:16px;padding:4px 13px;border-radius:100px;
  background:rgba(212,105,42,0.08);border:1.5px solid rgba(212,105,42,0.18);
  color:var(--accent);font-weight:700;
}

/* THOUGHT BUBBLE */
.thought-bubble{
  display:flex;flex-direction:column;align-items:center;
  margin:24px 0 28px;gap:12px;
}
.thought-badge{
  /* 圓形徽章：分析圖取代文字 */
  display:inline-flex;align-items:center;justify-content:center;
  background:var(--text-muted);color:#fff;
  font-size:11px;font-weight:700;letter-spacing:1px;
  padding:5px 14px;border-radius:100px;position:relative;
}
.thought-badge::before{
  content:'';display:inline-block;
  width:88px;height:88px;margin-right:6px;
  background:url(assets/analysis-badge.jpg) no-repeat center;
  background-size:contain;vertical-align:middle;
}
.thought-text{
  background:linear-gradient(135deg,rgba(61,43,31,0.04),rgba(61,43,31,0.08));
