}
.insight-box p{
  color:var(--text-dim);font-size:20px;max-width:560px;
  margin:0 auto;line-height:1.9;font-weight:500;
}

/* CLOSING */
.closing{
  text-align:center;padding:120px 32px;
  background:linear-gradient(180deg,var(--bg) 0%,var(--bg-warm) 100%);
}
.closing h2{font-size:clamp(28px,4vw,50px);font-weight:800;letter-spacing:-1px;margin-bottom:18px}
.closing>p{
  color:var(--text-dim);font-size:18px;max-width:480px;
  margin:0 auto 48px;line-height:1.8;
}
.closing-quote{
  font-size:clamp(18px,2.5vw,27px);font-weight:700;font-style:italic;
  max-width:720px;margin:0 auto 12px;line-height:1.65;color:var(--text);
}
.closing-quote::before{content:'「'}
.closing-quote::after{content:'」'}
.closing-attr{font-size:13px;color:var(--text-muted);margin-bottom:56px}
.tag-row{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}
.tag{
  padding:8px 20px;border-radius:100px;font-size:13px;font-weight:700;
